<?php
require __DIR__ . '/app/services.php';$u=require_login();$staff=in_array($u['role'],['Admin','Officer'],true);
if(request_post()){
    check_post();if(!$staff)fail('Only staff can record verified payments.',403);
    $fineId=(int)($_POST['fine_id']??0);$amount=(float)($_POST['amount']??0);$ref=trim((string)($_POST['reference']??''));$method=(string)($_POST['method']??'cash');
    if($fineId<1||!is_finite($amount)||$amount<=0||round($amount,2)!=$amount||$ref===''||strlen($ref)>100||!in_array($method,['cash','gcash','bank_transfer','other'],true)) {flash('Enter a valid fine, amount, payment method, and receipt/reference number.','error');go('fines.php');}
    try{
        db()->beginTransaction();
        $fine=one('SELECT id,student_id,amount,status FROM fines WHERE id=? FOR UPDATE',[$fineId]);
        if(!$fine || $fine['status']==='waived')throw new RuntimeException('Fine is missing or waived.');
        $already=(float)(one("SELECT COALESCE(SUM(pa.amount),0) AS paid FROM payment_allocations pa JOIN payments p ON p.id=pa.payment_id WHERE pa.fine_id=? AND p.status='verified'",[$fineId])['paid']??0);
        $balance=round((float)$fine['amount']-$already,2);
        if($amount>$balance+0.001)throw new RuntimeException('Payment exceeds remaining balance of '.pesos($balance).'.');
        run_sql("INSERT INTO payments(student_id,amount,reference_number,payment_method,status,received_by,verified_by,paid_at,verified_at) VALUES(?,?,?,?,'verified',?,?,NOW(),NOW())",[$fine['student_id'],$amount,$ref,$method,$u['id'],$u['id']]);
        $paymentId=(int)db()->lastInsertId();run_sql('INSERT INTO payment_allocations(payment_id,fine_id,amount) VALUES(?,?,?)',[$paymentId,$fineId,$amount]);
        $newStatus=($balance-$amount)<=0.001?'paid':'partially_paid';
        run_sql('UPDATE fines SET status=? WHERE id=?',[$newStatus,$fineId]);
        audit('payment_verified','payments',$paymentId,['fine_id'=>$fineId,'amount'=>$amount,'method'=>$method]);
        db()->commit();flash('Verified payment of '.pesos($amount).' recorded. Receipt: '.$ref);go('fines.php');
    }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();friendly_error($e,'Unable to record payment: '.$e->getMessage());go('fines.php');}
}
$studentId=$staff?max(0,(int)($_GET['student_id']??0)):(int)(mine()['id']??0);
$fines=$staff?get_fines($studentId?:null):get_fines($studentId?:-1);
$owing=array_sum(array_map(fn($f)=>$f['status']==='waived'?0:max(0,(float)$f['amount']-(float)$f['paid']),$fines));
page_header('Fines & Payments',$u);title_block($staff?'Manage Fines & Payments':'My Fines & Payments',$staff?'Track absence fines and issue verified payment records.':'View assessed fines, payment history and outstanding balances.');
?><div class="cards"><div class="card"><div class="kicker">Fine Records</div><div class="metric"><?=count($fines)?></div></div><div class="card"><div class="kicker">Unpaid Balance</div><div class="metric accent"><?=pesos($owing)?></div></div><div class="card"><div class="kicker">Verified Payments</div><div class="metric"><?php $paymentFilter=$staff?($studentId?' WHERE student_id='.$studentId:''):(' WHERE student_id='.$studentId);echo (int)(one("SELECT COUNT(*) n FROM payments WHERE status='verified'".$paymentFilter)['n']??0);?></div></div><div class="card"><div class="kicker">Absent Fine Rule</div><div class="metric">₱20</div><div class="footnote">Default amount per unexcused event absence</div></div></div>
<?php if($staff):?><section class="panel"><div class="row between"><h2>Filter Student</h2><form method="get" class="row"><input type="number" name="student_id" min="1" placeholder="Internal student ID" value="<?=h($studentId?:'')?>" style="width:175px;margin:0"><button class="btn btn-ghost">Filter</button><a class="btn btn-soft" href="<?=h(app_path('fines.php'))?>">All</a></form></div><h2>Record Verified Payment</h2><p class="hint">Enter the exact fine and an original receipt number. Payments are immediately verified by the logged-in staff account, with an audit record.</p><form method="post" class="form-grid wide" style="align-items:end"><?=csrf_field()?><label>Fine / Student<select name="fine_id" required><option value="">Select outstanding fine</option><?php foreach($fines as $f):if($f['status']==='waived' || (float)$f['amount']-(float)$f['paid']<=0.001)continue;?><option value="<?=h($f['id'])?>">#<?=h($f['id'])?> · Student <?=h($f['student_id'])?> · <?=h($f['title'])?> · <?=pesos((float)$f['amount']-(float)$f['paid'])?></option><?php endforeach;?></select></label><label>Amount<input type="number" name="amount" min="0.01" step="0.01" required></label><label>Receipt / Reference<input name="reference" maxlength="100" required placeholder="Unique receipt #"></label><label>Payment Method<select name="method"><option value="cash">Cash</option><option value="gcash">GCash</option><option value="bank_transfer">Bank Transfer</option><option value="other">Other</option></select></label><button class="btn btn-primary">Record Payment</button></form></section><?php endif; ?>
<section class="panel"><h2>Fine Ledger</h2><div class="table-scroll"><table class="table"><thead><tr><th>Fine #</th><th>Student</th><th>Event</th><th>Reason</th><th>Fine</th><th>Verified Paid</th><th>Balance</th><th>Status</th></tr></thead><tbody><?php foreach($fines as $f):?><tr><td><?=h($f['id'])?></td><td><?=h($f['student_id'])?></td><td><?=h($f['title'])?></td><td><?=h($f['reason'])?></td><td><?=pesos($f['amount'])?></td><td><?=pesos($f['paid'])?></td><td><strong><?=pesos($f['status']==='waived'?0:max(0,(float)$f['amount']-(float)$f['paid']))?></strong></td><td><?=status_badge($f['status'])?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$fines):?><p class="empty">No absence fines recorded.</p><?php endif;?></section>
<section class="panel"><h2>Payment History</h2><?php $payments=$staff?all('SELECT p.*,s.student_number FROM payments p JOIN students s ON s.id=p.student_id ORDER BY p.created_at DESC LIMIT 70'):all('SELECT p.*,s.student_number FROM payments p JOIN students s ON s.id=p.student_id WHERE p.student_id=? ORDER BY p.created_at DESC LIMIT 70',[$studentId]);?><div class="table-scroll"><table class="table"><thead><tr><th>Receipt #</th><th>Student ID</th><th>Amount</th><th>Method</th><th>Date</th><th>Status</th></tr></thead><tbody><?php foreach($payments as $p):?><tr><td><?=h($p['reference_number'])?></td><td><?=h($p['student_number'])?></td><td><?=pesos($p['amount'])?></td><td><?=h(ucwords(str_replace('_',' ',$p['payment_method'])))?></td><td><?=h($p['paid_at'])?></td><td><?=status_badge($p['status'])?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$payments):?><p class="empty">No payment records.</p><?php endif;?></section><?php page_footer();
